public class Main {
    public static void main(String[] args) {
        byte a = 10;
        short b = a;

        System.out.println(a);
        System.out.println(b);
    }
}

public class Main {
    public static void main(String[] args) {
        int a = 20;
        double b = a;

        System.out.println(b);
    }
}

public class Main {
    public static void main(String[] args) {
        short a = 120;
        byte b = (byte) a;

        System.out.println(a);
        System.out.println(b);
    }
}

public class Main {
    public static void main(String[] args) {
        int value = 65;
        char ch = (char) value;
        System.out.println(ch);
    }
}

